from lib import *
S = SS('n6')
steps = [
    step("默认 RedirectTrailingSlash=true(RedirectFixedPath 和 HandleMethodNotAllowed 默认是 false)。路由 /dir/ 被请求 /dir → 301 到 /dir/;路由 /file 被请求 /file/ → 301 到 /file;参数路由 /users/:id/ 请求 /users/7 → 301 /users/7/;带 query 的 /dir?x=1&y=2 重定向后 query 原样保留(/dir/?x=1&y=2)。路由和请求一致时直接 200。", t=tl(S(1)), mark=lidx(S(1), '/dir                   → 301', '/file/                 → 301', '/users/7               → 301', '/dir?x=1&y=2'), done=lidx(S(1), '/dir/                  → 200', '/file                  → 200'), kv=KV([['路由有 /,请求没有', '301 加上 /'], ['路由没有 /,请求有', '301 去掉 /'], ['query', '原样保留']], ['query'])),
    step("redirectRequest 的状态码只看方法:req.Method != GET 就用 307,否则 301。所以 GET 是 301;HEAD、POST、PUT、PATCH、DELETE、OPTIONS 都是 307;CONNECT 干脆不重定向,直接 404(handleHTTPRequest 里有 httpMethod != http.MethodConnect 的判断)。", t=tl(S(2)), mark=lidx(S(2), 'code = http.StatusTemporaryRedirect', 'HEAD   /x', 'CONNECT /x'), done=lidx(S(2), 'GET    /x', 'POST   /x'), b=bars([['GET', 301, '301'], ['HEAD / POST / PUT / PATCH / DELETE / OPTIONS', 307, '307'], ['CONNECT', 404, '404(不重定向)']], 404, done=[0], mark=[1, 2]), kv=KV([['GET', '301 Moved Permanently'], ['其他方法(含 HEAD)', '307 Temporary Redirect,保留方法和 body'], ['CONNECT', '不重定向']], ['其他方法(含 HEAD)'])),
    step("RedirectTrailingSlash=false 之后,/dir 直接 404。反向代理挂在子路径下时,X-Forwarded-Prefix 会进 Location:/app → /app/dir/;/app/ 也是 /app/dir/;恶意的 //evil.com 被 sanitizePathChars 去掉点号,变成 /evilcom/dir/;/a b;c 变成 /abc/dir/(只保留字母、数字、斜杠和连字符)。", t=tl(S(3)), mark=lidx(S(3), 'RedirectTrailingSlash = false', 'X-Forwarded-Prefix: "//evil.com"', 'X-Forwarded-Prefix: "/a b;c"'), done=lidx(S(3), 'X-Forwarded-Prefix: "/app"', 'X-Forwarded-Prefix: "/app/"'), kv=KV([['关掉之后', '/dir → 404'], ['X-Forwarded-Prefix', '拼进 Location'], ['过滤', '只保留字母数字、/、-']], ['过滤'])),
    step("真实的 http.Client 与真实的 http.Server(httptest.NewServer):服务只注册了 POST /upload/,客户端 POST /upload 带 body \"hello\":先收到 307,客户端按 307 的规则用同样的方法重发,服务端的 handler 只被调用一次,看到 POST /upload/ 和 body=\"hello\",最终 200。GET /old 不跟随时拿到 301 与 Location=/old/。", t=tl(S(4)), mark=lidx(S(4), '客户端被重定向到', 'body="hello"'), done=lidx(S(4), '最终响应:200', '301,Location=/old/'), kv=KV([['307 + POST', '客户端重发 POST,body 不丢'], ['handler 调用次数', '1 次(第一次请求没进 handler)'], ['GET 301', '客户端改成 GET 跟随']], ['307 + POST'])),
]
A = mkartn('n6', 6, 'Gin,RedirectTrailingSlash,301,307,重定向,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 RedirectTrailingSlash:路由与请求在结尾斜杠上不一致时,GET 返回 301、其他方法(含 HEAD)返回 307、CONNECT 直接 404,query 原样保留;X-Forwarded-Prefix 会进 Location 并过滤特殊字符;真实 HTTP 客户端遇到 307 时重发 POST 且 body 不丢。',
    '/dir 和 /dir/ 在 Gin 里是两条不同的路由,默认会互相重定向。这篇用状态码和 Location 把规则列清楚:什么时候是 301、什么时候是 307、query 和反向代理的前缀怎么处理,以及真实的 HTTP 客户端遇到这种重定向会怎样。',
    [('301 / 307', 'GET / 其他方法的重定向状态码'), ('1 次', '307 重定向后 POST /upload/ 的 handler 被调用次数,body 不丢'), ('/evilcom/dir/', 'X-Forwarded-Prefix 为 //evil.com 时的 Location')],
    [('默认就开着', '<p>Engine 的默认值是 <code>RedirectTrailingSlash=true</code>,<code>RedirectFixedPath=false</code>,<code>HandleMethodNotAllowed=false</code>。注册 <code>/dir/</code> 之后请求 <code>/dir</code> 会 301 到 <code>/dir/</code>,反过来 <code>/file</code> 注册了就请求 <code>/file/</code> 则 301 去掉斜杠。参数路由同样适用,query 保持原样。</p>'),
     ('301 还是 307', '<p>状态码只由方法决定:<code>GET</code> 用 301,其他方法用 307。这也包括 <code>HEAD</code>——HEAD 拿到的是 307。307 要求客户端用相同方法和 body 重发,所以 POST 到 <code>/upload</code>、而路由注册成 <code>/upload/</code> 时,不会像 302 那样被降级成 GET。CONNECT 完全不做重定向。</p>'),
     ('关闭与反向代理', '<p>关掉 <code>RedirectTrailingSlash</code> 后,结尾斜杠不一致就是普通的 404。挂在反向代理子路径下时,代理设置的 <code>X-Forwarded-Prefix</code> 会拼进 Location,Gin 先用 <code>sanitizePathChars</code> 只保留字母、数字、斜杠和连字符,所以带 <code>.</code> 的 <code>//evil.com</code> 变成 <code>/evilcom/</code>,不会产生开放重定向。</p>'),
     ('真实客户端', '<p>Go 的 <code>http.Client</code> 遇到 307 会用同一方法重发,body 也被带上:服务端 handler 只被调用一次,拿到完整的 <code>hello</code>。GET 的 301 则被客户端当作普通重定向。是否缓存 301、其他语言客户端对 307 的处理不一定相同,本文没有验证。</p>')],
    steps,
    [ENV_N_GIN + '。前三节用 httptest 直接调用 ServeHTTP,第四节用 httptest.NewServer 起真实的本机 HTTP 服务和 Go 的 http.Client;每种情形各一次',
     '没有验证:浏览器对 301 的永久缓存行为;curl、Python requests、浏览器对 307 + POST 的处理;HTTP/2 下的行为;非 ASCII 路径的重定向 Location 编码;RemoveExtraSlash 与 RedirectTrailingSlash 同时打开时的交互(下一篇与后面的文章再看)'],
    '尾斜杠重定向')
